const navKey=p=>`${p[0]},${p[1]}`;
const samePos=(a,b)=>a?.[0]===b?.[0]&&a?.[1]===b?.[1];
const navDirDelta={U:[0,-1],R:[1,0],D:[0,1],L:[-1,0]};
