 if(!level){S.navigationDone[S.day]=true;startScene('lighthouse');return}
 const saved=S.navigationProgress[S.day],effects=navigationRippleEffects(),arrows={U:'↑',R:'→',D:'↓',L:'←'},effectLog=[];
