 navigationRuntime={level,effects,effectiveLimit:level.moveLimit+effects.bonus,pos:[...(saved?.pos||level.start)],collected:new Set(saved?.collected||[]),activated:new Set(saved?.activated||[]),rescued:new Set(saved?.rescued||[]),moves:saved?.moves||0,assisted:!!saved?.assisted,log:[...(saved?.log||[...effectLog,"Prepare for your first steer, following the sound of the waves."])],history:(saved?.history||[]).map(h=>({...h,pos:[...h.pos],collected:[...(h.collected||[])],activated:[...(h.activated||[])],rescued:[...(h.rescued||[])],log:[...(h.log||[])]}))};
