function navigationGateOpen(gate,activated=navigationRuntime.activated){return navigationRuntime.level.switches.some(sw=>activated.has(sw.id)&&(sw.opens||[]).includes(gate.id))}
function navigationBlocked(pos,activated=navigationRuntime.activated){const l=navigationRuntime.level;if(pos[0]<0||pos[0]>=6||pos[1]<0||pos[1]>=6)return"Outside the map there is only reef and fog.";if(l.reefs.some(p=>samePos(p,pos)))return"A reef blocks the shipping route.";const gate=l.gates.find(g=>samePos(g.pos,pos));if(gate&&!navigationGateOpen(gate,activated))return"It's a locked door. You must first find connected papers or structures.";return''}
