function tryNavigationMove(dir){if(!navigationRuntime||!$('#navigationDialog').open)return;const result=resolveNavigationMove(dir);if(result.error){navigationRuntime.log=[result.error,...navigationRuntime.log].slice(0,4);sfx('wrong');renderNavigation();return}navigationRuntime.history.push(navSnapshot());navigationRuntime.pos=result.pos;navigationRuntime.activated=result.activated;navigationRuntime.collected=result.collected;navigationRuntime.rescued=result.rescued;navigationRuntime.moves++;navigationRuntime.log=[...(result.events.length?result.events:["Only the waves break and there is no signal."]),...navigationRuntime.log].slice(0,4);sfx('step');persistNavigation();renderNavigation();const encounter=nextUnseenNavigationEncounter();if(encounter){$('#navigationDialog').close();openNavigationEncounter(encounter.signalId);return}if(navigationComplete())setTimeout(completeNavigation,220)}
function nextUnseenNavigationEncounter(){if(!navigationRuntime)return null;return navigationEncounters.find(e=>e.day===S.day+1&&navigationRuntime.collected.has(e.signalId)&&!S.navigationEncounters[`${S.day}-${e.signalId}`])||null}
function openNavigationEncounter(signalId){const data=navigationEncounters.find(e=>e.day===S.day+1&&e.signalId===signalId);if(!data){S.navigationEncounters[`${S.day}-${signalId}`]={choiceId:'missing-data'};openNavigation();return}const pending=S.navEncounterPending;if(pending?.day===S.day&&pending.signalId===signalId&&pending.choice){showStory("night sea signal",data.title,[pending.choice.result],commitNavigationEncounter);return}S.navEncounterPending={day:S.day,signalId,choice:null};autosave(false);const choices=data.choices.map(o=>({label:o.label,result:o.result,onPick:()=>{S.navEncounterPending.choice={id:o.id,stat:o.stat,result:o.result,title:data.title};autosave(false)}}));showStory("night sea signal",data.title,data.pages,commitNavigationEncounter,choices)}
function commitNavigationEncounter(){const pending=S.navEncounterPending;if(!pending?.choice)return;const key=`${pending.day}-${pending.signalId}`,choice=pending.choice;if(!S.navigationEncounters[key]){if(choice.stat)S[choice.stat]++;S.choicesTrail.push({day:S.day,text:`Navigational signals ·${choice.title}: ${choice.id}`,stat:choice.stat});S.navigationEncounters[key]={choiceId:choice.id,stat:choice.stat,title:choice.title}}S.navEncounterPending=null;autosave();const next=nextUnseenNavigationEncounter();if(next){openNavigationEncounter(next.signalId);return}if(navigationComplete()){setTimeout(completeNavigation,180);return}openNavigation()}
function navigationComplete(){const l=navigationRuntime.level;return samePos(navigationRuntime.pos,l.goal)&&navigationRuntime.collected.size===l.signals.length&&navigationRuntime.activated.size===l.switches.length&&navigationRuntime.rescued.size===l.survivors.length}
