 const r=navigationRuntime,l=r.level,grid=$('#navigationGrid');grid.innerHTML='';
 for(let y=0;y<6;y++)for(let x=0;x<6;x++){const pos=[x,y],cell=document.createElement('button'),icons=[],labels=[];cell.className='nav-cell';cell.setAttribute('role','gridcell');const reef=l.reefs.some(p=>samePos(p,pos)),gate=l.gates.find(g=>samePos(g.pos,pos)),current=l.currents.find(c=>samePos(c.pos,pos)),signal=l.signals.find(s=>samePos(s.pos,pos)),sw=l.switches.find(s=>samePos(s.pos,pos)),survivor=l.survivors.find(s=>samePos(s.pos,pos));if(reef){cell.classList.add('reef');icons.push('▲');labels.push("reef")}if(gate){cell.classList.add('gate');if(navigationGateOpen(gate))cell.classList.add('open');icons.push(navigationGateOpen(gate)?'□':'▣');labels.push(navigationGateOpen(gate)?"open door":"locked door")}if(current){cell.classList.add('current');icons.push('≋');labels.push(`${current.dir}direction tide`)}if(signal&&!r.collected.has(signal.id)){icons.push('✦');labels.push("memory signal")}if(sw){icons.push(r.activated.has(sw.id)?'◌':'⚙');labels.push(r.activated.has(sw.id)?"on switch":"switch")}if(survivor&&!r.rescued.has(survivor.id)){icons.push('◉');labels.push("drifter")}if(samePos(pos,l.goal)){cell.classList.add('goal');icons.push('◎');labels.push("lighthouse buoy")}if(samePos(pos,r.pos)){cell.classList.add('player');icons.push('◆');labels.push("Current ship position")}cell.innerHTML=`<span class="cell-icons">${icons.join(' ')||'·'}</span>${current?`<span class="current-arrow">${{U:'↑',R:'→',D:'↓',L:'←'}[current.dir]}</span>`:''}`;cell.setAttribute('aria-label',`${x+1}heat${y+1}row,${labels.join(', ')||"empty sea"}`);const dx=x-r.pos[0],dy=y-r.pos[1];if(Math.abs(dx)+Math.abs(dy)===1)cell.onclick=()=>tryNavigationMove(dx===1?'R':dx===-1?'L':dy===1?'D':'U');else{cell.tabIndex=-1;cell.setAttribute('aria-disabled','true')}grid.appendChild(cell)}
