function openCollection(){const meta=readMeta(),names={release:"The Light We Let Go",stars:"A Course Written in Stars",remain:"One More Beautiful Night",dawn:"The Morning After Memory"};$('#collectionContent').innerHTML=`<p>Ending discovered${meta.endingsSeen.length}/4 · Unlocked Achievements${Object.keys(meta.achievements).length}/${Object.keys(achievementDefs).length}</p>${['release','stars','remain','dawn'].map((id,i)=>`<article class="entry ${meta.endingsSeen.includes(id)?'solved':'locked'}"><p class="speaker">ENDING ${i+1}</p><h3>${meta.endingsSeen.includes(id)?names[id]:'???'}</h3><p>${meta.endingsSeen.includes(id)?"This ending will be preserved after the new game.":"This is the light that has not yet been selected by the lighthouse."}</p></article>`).join('')}`;$('#collectionDialog').showModal()}
