function begin(fresh){initAudio();if(fresh){S=freshState();storageRemove(SAVE_V2);autosave()}else if(!load())return;showScreen('game');renderMap();if(S.ending){ending(S.ending);return}if(openFinalDayRipples())return;if(S.atFinalChoice){S.broadcast?.completed?finalChoice():openFinalBroadcast();return}if(S.day===6&&S.storm?.completed&&!S.broadcast?.completed){openFinalBroadcast();return}if(openPendingRipples())return;if(S.day===6&&S.storm&&(S.storm.pending||S.storm.stage>0)&&!S.storm.completed){openStormClimax();return}if(S.navEncounterPending?.day===S.day){openNavigation();$('#navigationDialog').close();openNavigationEncounter(S.navEncounterPending.signalId);return}if(S.navigationProgress[S.day]&&!S.navigationDone[S.day]){openNavigation();return}if(S.pending&&S.pending.day===S.day&&locs[S.pending.loc]){S.current=S.pending.loc;renderMap();if(S.pending.choice?.result)showStory(people[S.current][0],"What the choice leaves behind",[S.pending.choice.result],()=>commitVisit(S.current,S.pending.choice.result));else startScene(S.pending.loc,true);return}const all=routes[S.day].every(id=>S.visited[`${S.day}-${id}`]);if(all&&!S.navigationDone[S.day]){S.current='lighthouse';renderMap();openNavigation();return}if(all&&!S.puzzleDone[S.day]){openPuzzle();return}if(all&&S.puzzleDone[S.day]){afterVisit();return}if(fresh)showStory("Mira","Prologue",["When you open your eyes, the sea is darker than the stars. The boat that brought you here is gone. In your hand is a single box of dry matches.","The lighthouse above the cliffs flashes three times—not a distress call, but the wink of someone who recognizes you.","A note in your pocket bears a single line in your handwriting: “Extinguish the light before the seventh dawn.”"],()=>{})}
